    private Transaction multisigEnableTransaction(
        final KeyPair multisigKeyPair,
        final List&lt;KeyPair&gt; cosignatoryKeyPairs,
        final int approvalDelta
    ) throws IOException {
        final List&lt;SizePrefixedMultisigAccountModificationDescriptor&gt;
