    @OnMessage
    public void onMessage(final String rawFrame) throws IOException {
        if ("o".equals(rawFrame)) {
            openFuture.complete(null);
            return;
        }
        if (!rawFrame.startsWith("a"))
            return;
        for (final JsonNode payload
            : JSON_MAPPER.readTree(rawFrame.substring(1))) {
